package selfcheck
import("testing";"task143-batchreactor/internal/campaign";"task143-batchreactor/internal/model";"task143-batchreactor/internal/report")
func TestBug07_LightCleaningCreatesVisibleChangeover(t *testing.T){if model.CleaningLight.CleaningDuration()!=600{t.Fatal("light cleaning not 600s")};a,b:=exothermicRecipe(),adiabaticRecipe();rc:=safeReactor();items:=[]model.CampaignItem{{CampaignID:"c",Seq:1,RecipeID:"a",ReactorID:"r",BatchCount:1},{CampaignID:"c",Seq:2,RecipeID:"b",ReactorID:"r",BatchCount:1}};p,_:=campaign.Plan(campaign.PlanInput{Items:items,Recipes:map[string]model.Recipe{"a":a,"b":b},Reactors:map[string]model.Reactor{"r":rc},StartAt:1,Matrix:func(_, _ string)model.CleaningSeverity{return model.CleaningLight}});if p.Batches[1].CleaningBefore!=600{t.Fatalf("changeover=%v",p.Batches[1].CleaningBefore)};g:=report.Gaps([]report.TimelineWindow{{ReactorID:"r",BatchID:"a",Start:1,End:10},{ReactorID:"r",BatchID:"b",Start:20,End:30}});if len(g)!=1||g[0].Seconds!=10{t.Fatalf("gap=%+v",g)}}
